/* ============================================================
   QQ 风格聊天界面 - 白色顶栏版（无毛玻璃）
   ============================================================ */

:root {
    /* 背景与整体氛围 */
    --chat-bg-blur: 0px;
    --chat-bg-overlay: transparent;

    /* 头部区域 - QQ 白 */
    --chat-header-bg: #ffffff;
    --chat-header-blur: 0px;
    --chat-header-border: 1px solid #e5e5e5;
    --chat-header-title-color: #1a1a1a;
    --chat-header-title-size: 17px;
    --chat-header-title-weight: 600;
    --chat-header-subtitle-color: #999999;
    --chat-header-icon-color: #333333;

    /* 自己发出的气泡 - QQ 标准蓝 */
    --bubble-me-bg: #0B84FF;
    --bubble-me-color: #ffffff;
    --bubble-me-border: none;
    --bubble-me-shadow: 0 2px 6px rgba(11, 132, 255, 0.25);
    --bubble-me-radius: 18px;
    --bubble-me-radius-first: 18px 18px 4px 18px;
    --bubble-me-radius-mid: 18px 4px 4px 18px;
    --bubble-me-radius-last: 18px 4px 18px 18px;

    /* 对方气泡 - 浅灰 */
    --bubble-them-bg: #f0f0f0;
    --bubble-them-color: #1a1a1a;
    --bubble-them-border: none;
    --bubble-them-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
    --bubble-them-radius: 18px;
    --bubble-them-radius-first: 18px 18px 18px 4px;
    --bubble-them-radius-mid: 4px 18px 18px 4px;
    --bubble-them-radius-last: 4px 18px 18px 18px;

    /* 输入区域 - 浅灰 */
    --input-area-bg: #f8f8f8;
    --input-area-blur: 0px;
    --input-area-border-top: 1px solid #e5e5e5;

    /* 输入框 - 纯白 */
    --input-box-bg: #ffffff;
    --input-box-color: #1a1a1a;
    --input-box-placeholder: #999999;
    --input-box-radius: 22px;
    --input-box-padding: 8px 16px;
    --input-box-border: 1px solid #e0e0e0;
    --input-box-blur: none;
    --input-box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);

    /* 发送按钮 - QQ 蓝 */
    --send-btn-bg: #0B84FF;
    --send-btn-color: #ffffff;
    --send-btn-size: 34px;
    --send-btn-radius: 50%;
    --send-btn-shadow: 0 2px 6px rgba(11, 132, 255, 0.35);

    --plus-btn-color: #666666;

    --timestamp-color: rgba(0, 0, 0, 0.4);
    --date-divider-bg: rgba(0, 0, 0, 0.06);
    --date-divider-color: rgba(0, 0, 0, 0.35);
}

/* ===== 1. 头部 - QQ 白色顶栏 ===== */

.chat-detail-screen .chat-header-custom {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 10 !important;
    background: #ffffff !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: 1px solid #e5e5e5 !important;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04) !important;
    height: auto !important;
    min-height: 96px !important;
    align-items: flex-start !important;
    padding-top: max(var(--nuo-safe-top), 12px) !important;
    padding-left: 12px !important;
    padding-right: 12px !important;
    padding-bottom: 8px !important;
}

/* 消息列表顶部留白 */
.chat-message-list-custom {
    padding-top: calc(max(var(--nuo-safe-top), 12px) + 84px) !important;
    padding-bottom: calc(78px + min(env(safe-area-inset-bottom, 0px), 34px)) !important;
}

/* 居中头像 + 昵称区域 */
.chat-detail-screen .header-profile-section {
    position: absolute !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    flex-direction: column !important;
    gap: 4px !important;
    align-items: center !important;
    top: max(var(--nuo-safe-top), 6px) !important;
    z-index: 1;
    pointer-events: none;
}

/* 头像 - 无边框或细灰边 */
.chat-detail-screen .header-avatar-container {
    width: 72px !important;
    height: 72px !important;
    border-radius: 50% !important;
    border: 2px solid #f0f0f0 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06) !important;
}

/* 昵称 - 纯黑文字，无背景 */
.chat-detail-screen .chat-header-title {
    font-size: 17px !important;
    font-weight: 600 !important;
    color: #1a1a1a !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    border-radius: 0 !important;
    padding: 2px 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin-top: 4px !important;
    white-space: nowrap !important;
    letter-spacing: 0.3px !important;
}

/* 在线状态 - 浅灰小字 */
.chat-detail-screen .chat-header-subtitle {
    display: flex !important;
    font-size: 11px !important;
    color: #999999 !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    padding: 0 !important;
    border: none !important;
    margin-top: 0 !important;
}

/* 返回按钮 - 纯灰 */
.chat-detail-screen .header-btn-back {
    color: #333333 !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    border-radius: 50% !important;
    height: 38px !important;
    width: 38px !important;
    min-width: 38px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    position: relative;
    z-index: 2;
    padding: 0 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
}
.chat-detail-screen .header-btn-back:active {
    background: rgba(0, 0, 0, 0.05) !important;
    transform: scale(0.92) !important;
}
.chat-detail-screen .header-btn-back svg {
    width: 22px !important;
    height: 22px !important;
    color: #333333 !important;
}

/* 右侧操作按钮 - 纯灰图标 */
.chat-detail-screen .chat-header-custom > div:last-child {
    position: relative;
    z-index: 2;
    gap: 4px !important;
}

.chat-detail-screen .header-action-btn {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    border-radius: 50% !important;
    width: 38px !important;
    height: 38px !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    color: #333333 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
}
.chat-detail-screen .header-action-btn:active {
    background: rgba(0, 0, 0, 0.05) !important;
    transform: scale(0.92) !important;
}
.chat-detail-screen .header-action-btn svg {
    width: 20px !important;
    height: 20px !important;
    color: #333333 !important;
}

/* ===== 2. 头像显示 ===== */

.msg-avatar-custom {
    display: flex !important;
    width: 40px !important;
    height: 40px !important;
    border-radius: 50% !important;
    flex-shrink: 0 !important;
    border: 1px solid rgba(0, 0, 0, 0.06) !important;
}

/* ===== 3. 气泡 - 纯色 ===== */

.bubble-them-custom {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    background: #f0f0f0 !important;
    color: #1a1a1a !important;
    border: none !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05) !important;
}

.bubble-me-custom {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    background: #0B84FF !important;
    border: none !important;
    box-shadow: 0 2px 6px rgba(11, 132, 255, 0.25) !important;
    color: #ffffff !important;
}

/* ===== 4. 输入区域 ===== */

.input-area-custom {
    position: absolute !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 60 !important;
    background: #f8f8f8 !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-top: 1px solid #e5e5e5 !important;
    padding: 10px 12px 10px 12px !important;
    padding-bottom: calc(10px + min(env(safe-area-inset-bottom, 0px), 34px)) !important;
}

.input-row-wrapper {
    gap: 8px !important;
    align-items: flex-end !important;
}

.input-btn-plus {
    background: #e8e8e8 !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 1px solid #d0d0d0 !important;
    color: #666666 !important;
    border-radius: 50% !important;
    width: 38px !important;
    height: 38px !important;
    margin-right: 0 !important;
    margin-bottom: 4px !important;
    flex-shrink: 0;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
}
.input-btn-plus:active {
    background: #d5d5d5 !important;
    transform: scale(0.92) !important;
}
.input-btn-plus svg {
    stroke-width: 1.5;
    width: 22px !important;
    height: 22px !important;
}

.input-action-bar-custom {
    padding: 4px 8px 4px 16px !important;
    min-height: 46px !important;
    align-items: center !important;
    background: #ffffff !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 24px !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04) !important;
}

.input-box-custom {
    margin-bottom: 0 !important;
    font-size: 16px !important;
    padding-right: 4px !important;
    color: #1a1a1a !important;
    -webkit-text-fill-color: #1a1a1a !important;
}
.input-box-custom::placeholder {
    color: #999999 !important;
    -webkit-text-fill-color: #999999 !important;
    opacity: 1 !important;
}

.input-action-bar-custom > div:last-child {
    margin-bottom: 0px !important;
    gap: 4px !important;
    height: 100%;
    align-items: center;
}

.input-btn-sticker,
.input-btn-ai,
.input-btn-mic {
    display: flex !important;
    opacity: 0.6 !important;
    color: #666666 !important;
    margin-bottom: 0px !important;
    padding: 6px !important;
    align-items: center !important;
    transition: opacity 0.2s !important;
}
.input-btn-sticker:active,
.input-btn-ai:active,
.input-btn-mic:active {
    opacity: 1 !important;
}
.input-btn-mic svg,
.input-btn-sticker svg,
.input-btn-ai svg {
    width: 22px !important;
    height: 22px !important;
}

.send-btn-custom {
    background: #0B84FF !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    border-radius: 50% !important;
    width: 34px !important;
    height: 34px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    box-shadow: 0 2px 6px rgba(11, 132, 255, 0.35) !important;
    transition: all 0.2s ease !important;
}
.send-btn-custom:active {
    transform: scale(0.9) !important;
    background: #0066CC !important;
}
.send-btn-custom svg {
    margin-left: 2px;
    color: #fff !important;
    width: 18px !important;
    height: 18px !important;
}

/* ===== 5. 更多菜单 ===== */

.input-area-custom .more-options-popup {
    overflow: hidden !important;
    background: #ffffff !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 1px solid #e5e5e5 !important;
    border-radius: 14px !important;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.12) !important;
    padding: 6px !important;
}
.input-area-custom .more-options-item-row {
    transition: background 0.15s ease !important;
    border-radius: 10px !important;
    padding: 10px 14px !important;
    background: transparent !important;
    border-bottom: 1px solid #f0f0f0 !important;
}
.input-area-custom .more-options-item-row:last-child {
    border-bottom: none !important;
}
.input-area-custom .more-options-item-row:hover,
.input-area-custom .more-options-item-row:active {
    background: #f5f5f5 !important;
}
.input-area-custom .more-options-item-row span,
.input-area-custom .more-options-item-row * {
    color: #1a1a1a !important;
    font-size: 14px !important;
    font-weight: 500 !important;
}
.input-area-custom .more-options-item-row svg {
    color: #666666 !important;
    stroke: #666666 !important;
}
